namespace BlazorNotifications.Services;

public record Notification(int Id, string Message, DateTime Timestamp);

public class NotificationService
{
    private int _nextId = 1;
    private readonly List<Notification> _notifications = new();
    private readonly Lock _lock = new();

    public NotificationService()
    {
        // Seed with initial fake data.
        _notifications.AddRange(new[]
        {
            CreateNotification("Welcome to the notifications page!"),
            CreateNotification("Your profile was updated successfully."),
            CreateNotification("New comment on your post.")
        });
    }

    /// <summary>Returns all notifications created so far.</summary>
    public List<Notification> GetAll()
    {
        lock (_lock)
        {
            return _notifications.ToList();
        }
    }

    /// <summary>Returns only notifications with an Id greater than <paramref name="sinceId"/>.</summary>
    public List<Notification> GetSince(int sinceId)
    {
        lock (_lock)
        {
            return _notifications.Where(n => n.Id > sinceId).ToList();
        }
    }

    /// <summary>
    /// Simulates new notifications arriving. Called by a hosted background service
    /// so there is always something new to poll.
    /// </summary>
    public void AddRandom()
    {
        string[] templates =
        [
            "Server deployment completed.",
            "A user signed up.",
            "Disk usage exceeded 80%.",
            "Backup finished successfully.",
            "New pull request opened.",
            "CI build passed.",
            "Payment received.",
        ];

        lock (_lock)
        {
            var msg = templates[Random.Shared.Next(templates.Length)];
            _notifications.Add(CreateNotification(msg));
        }
    }

    private Notification CreateNotification(string message) =>
        new(_nextId++, message, DateTime.UtcNow);
}

namespace BlazorNotifications.Services;

/// <summary>
/// Background hosted service that periodically adds fake notifications
/// so the polling page always has something new to show.
/// </summary>
public class NotificationGeneratorService(NotificationService notifications) : BackgroundService
{
    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(8), stoppingToken);
            notifications.AddRandom();
        }
    }
}

@page "/notifications"
@rendermode InteractiveServer
@implements IDisposable
@inject BlazorNotifications.Services.NotificationService NotificationSvc

<PageTitle>Notifications</PageTitle>

<h1>
    Notifications
    <span class="badge bg-primary rounded-pill ms-2">@notifications.Count</span>
</h1>

<ul class="list-group mt-3">
    @foreach (var n in notifications)
    {
        <li class="list-group-item d-flex justify-content-between align-items-start">
            <span>@n.Message</span>
            <small class="text-muted">@n.Timestamp.ToString("HH:mm:ss")</small>
        </li>
    }
</ul>

@code {
    private List<BlazorNotifications.Services.Notification> notifications = new();
    private CancellationTokenSource? _cts;
    private int _lastSeenId;

    protected override void OnInitialized()
    {
        // Runs during SSR *and* during the interactive reconnect.
        // Loads initial data so the server-rendered HTML already contains notifications.
        notifications = NotificationSvc.GetAll();
        _lastSeenId = notifications.Count > 0 ? notifications.Max(n => n.Id) : 0;
    }

    protected override void OnAfterRender(bool firstRender)
    {
        if (firstRender)
        {
            // OnAfterRender only fires on the interactive (SignalR) render,
            // never during static SSR — so the polling loop starts only when
            // the page is truly live in the browser.
            _cts = new CancellationTokenSource();
            _ = PollForNotificationsAsync(_cts.Token);
        }
    }

    private async Task PollForNotificationsAsync(CancellationToken ct)
    {
        while (!ct.IsCancellationRequested)
        {
            await Task.Delay(TimeSpan.FromSeconds(5), ct).ConfigureAwait(false);

            var newer = NotificationSvc.GetSince(_lastSeenId);
            if (newer.Count > 0)
            {
                _lastSeenId = newer.Max(n => n.Id);
                await InvokeAsync(() =>
                {
                    notifications.AddRange(newer);
                    StateHasChanged();
                });
            }
        }
    }

    public void Dispose()
    {
        _cts?.Cancel();
        _cts?.Dispose();
    }
}

